    "desc_root_port": "通往 Root 根网桥的最优路径。每个非根交换机只能有一个。在 RSTP 中，Proposal/Agreement 交换完成后，它会立刻进入 Forwarding 转发状态。",
    "desc_designated_port": "每个 LAN 局域网段上指向 Root 根方向的最佳网桥端口。它是该网段中唯一负责发送/转发 BPDU 的端口。",
    "desc_alternate_port": "只在 RSTP 出现。指代从其他网桥收到更优 BPDU 的端口。如果上行主链路故障，它能绕过所有计时器等待并瞬间无缝切换成 Root Port 根端口。",
    "desc_backup_port": "只在 RSTP 出现。指代在同一局域网段 (集线器或自环链路) 收到了本机自己发出的更优 BPDU 的端口。由于集线器已经被淘汰，在现代网络中极罕见。",
    "desc_non_designated": "只在传统 STP (802.1D) 中出现。接收 BPDU 但不会转发用户数据。当拓扑发生变更时，它需要老老实实经历 Listening → Learning 阶段的漫长等待。",
    "desc_edge_port": "一旦链路连通就直接跳入 Forwarding 状态 (也就是跳过侦听/学习过程)。但是如果收到任何 BPDU，它会产生拓扑变更 TCN 事件并降级。应当仅仅将最终终端设备接入此类端口。",
