    "vpc_type1_desc": "两侧的所有相关参数必须丝毫不差，否则相关 vPC 将被强制挂起 (Suspending) 停止工作 — 包括 MTU，使用的 STP 模式，速率/双工类型以及接口被允许透传的 VLAN 列表。",
    "vpc_type2_desc": "两侧参数应当保持一致。这类参数不同时并不会直接干掉 vPC 通道，但特定的业务功能可能会存在异常隐患 — 例如 Syslog 设置，SNMP 参数，或 IGMP Snooping 开关等。",
