    "how_maps_desc_1": "1. 您的交换机会基于当前选择的散列算法计算出一个 3 位二进制值作为 Hash Result 哈希结果值 (即 RBH 值)。",
    "how_maps_desc_2": "2. 在聚合捆绑包中的每一条物理网线接口都会被分配到一个与之对应的逻辑标号 (从 0 直到 {links-1})。",
    "how_maps_desc_3": "通常 Cisco 在给接口分配这个序号时，会优先将最小的接口 ID 绑定给标号为 0 的通道。",
    "how_maps_desc_4": "3. 硬件层面一共有 8 个可用的分配槽位 (编号 0-7)，它们被尽量均匀地打散分配给了这几条活动连接。",
    "how_maps_desc_5": "4. 因为当前的数据流计算得出的哈希值是 {rbh}，那么这个流量就会命中这个标号为 {idx} ({label}) 的通信物理接口。",
