    "area_stub": "Stub (末梢被堵住的区域)：它非常轻量。完全杜绝了 Type 5 类繁杂的外部路由流入，统统用一条 0.0.0.0 的终极默认路由代替指向上级。",
    "area_totally": "Totally Stubby (完全堵死末梢区域)：最为极端的瘦身。不但外部的 Type 5 进不来，连其它相邻区域跑来的 Type 3 汇总通告也全被屏蔽，只能看一条唯一的默认路由。",
    "area_nssa": "NSSA (Not-So-Stubby Area 不太末梢的特殊区域)：具备 Stub 的优良封闭特质，但是给那些需要通过此地去连接外部不合规网络留个了一扇后门，采用 Type 7 特例路由穿透传达。",
    "bgp_dive": "BGP 边界网关协议 (路径矢量算法) 选路深潜",
