    "geolocation": "通过基站和定位所被系统粗略圈画并且反推定位评估得出出来的具体属于在现实国家及地球上详细到门牌号或到区段所在的地球方位地理位置落脚大致大致物理地址的追踪溯源判断评估归属落脚点",
    "prefixes_v4": "这名拥有如此顶级骨干权限和巨大特权大佬所霸占划片统领并在全网通报通告拥有的老一代遗留下来的全部 IPv4 旗下所有被招安小弟的前缀地盘小片网段总数统计量合计高达 ({count} 之多)",
    "prefixes_v6": "这是此家极富先见之明极度庞大甚至掌握未来科技骨干通讯命脉权限所早早跑马圈地占据统领全网那些新世代且数量更是吓死人堪称无限恐怖深渊海量恐怖数量的全部 IPv6 新型划定好片区归属的前缀拥有领土及版图数量统计合集达到有令人窒息的大约这庞大数量这么多合计数字 ({count}) 个巨形超级网络段区块地盘",
    "rir": "这是在世界上唯一只有这世界上只存在五家的被联合国所特许并在全球按照各个大洲物理区域所划分具有至高绝对发放门牌特权用来直接指派给你们分配以及垄断注册这种骨干资源的顶层地区级别区域的超级登记指派发放管理总局上层监管领导大老总 RIR 权威组织监管局简称",
    "website": "在这个互联网浩瀚星海茫茫里，能够作为可以被这帮背后隐藏金主公司拿出来公诸于众被宣传，可以在网页里作为用来直接让公众了解他们存在唯一在官方上并且是官方用来正式联络并且公布给广大网民和官方权威发布大门面门市所注册挂牌官方互联网网址",
