    "sysctl_title": "Linux TCP 调优 (sysctl)",
    "sysctl_subtitle": "生成 sysctl 命令，根据您的路径参数优化 Linux TCP 缓冲区和拥塞控制。",
    "sysctl_algo": "拥塞控制算法",
    "sysctl_apply_hint": "应用命令：sysctl -p /etc/sysctl.d/99-tcp-tuning.conf。数值根据您的 BDP 计算。",
    "ref_title": "算法参考",
    "ref_reno_desc": "经典的 AIMD 算法。慢启动在每个 RTT 将 cwnd 翻倍，直到达到 ssthresh。拥塞避免每个 RTT 增加约 1 个段。收到 3 个冗余 ACK 时：ssthresh = cwnd/2, cwnd = ssthresh。超时时：cwnd = 1 MSS。公平但丢包后在高 BDP 路径上利用率不足。",
    "ref_cubic_desc": "Linux 默认算法。使用三次函数 W(t) = C(t-K)^3 + W_max (C=0.4, beta=0.7)。丢包后，cwnd 降至 W_max 的 70%，然后通过凹凸曲线增长。在长肥网络 (LFN) 上比 Reno 更激进。K = (W_max * 0.3 / C)^(1/3)。",
    "ref_bbr_desc": "Google 基于模型的算法。不以丢包作为信号，而是估算瓶颈带宽和最小 RTT。阶段：Startup (2.89x 增益)、Drain, ProbeBW (8 阶段增益循环: 1.25/0.75/1...)、ProbeRTT (每 ~10 秒 4 个段)。即使有丢包也能达到满吞吐量。",
