    "plat_iosxr_notes": "IOS-XR 文件系统使用 disk0: 或 disk1: 而非 flash:。XR 中的 SCP/SFTP 命令会交互式提示输入用户密码。路由上下文（VRF）可以全局配置。",
    "plat_nxos_notes": "NX-OS 默认使用 bootflash:。请用 \"dir bootflash:\" 检查文件系统空间。VRF 必须能与服务器进行 IP 通信；请检查默认路由或管理 VRF。",
    "plat_junos_notes": "Junos 上复制的文件存放在 /var/tmp/ 或 /var/db/config/。请用 \"show system storage\" 检查磁盘空间。TFTP 传输可能需要配置 Junos 路由协议，或使用 routing-instance 关键字。",
    "plat_eos_notes": "Arista 设备使用 flash:。请用 \"dir flash:\" 验证。为获得高吞吐量，Arista 支持高度优化的原生 HTTP/HTTPS 复制。",
    "plat_fortios_notes": "FortiOS 的 TFTP 恢复会替换启动镜像并自动重启设备。请谨慎使用。务必事先保存配置文件。",
    "plat_panos_notes": "Palo Alto PAN-OS 需要显式的 CLI 管理员权限才能运行软件导入命令。软件也可以直接从 Palo Alto 官方支持更新下载。",
    "plat_linux_notes": "请检查目标目录的读写权限。确保已安装客户端（scp、curl）。通过 curl/wget 进行的 HTTP/HTTPS 传输可以高度并行化。",
    "plat_f5_notes": "请检查 bigstart 进程和 F5 管理路由权限。目标文件夹 /shared/images/ 是 F5 ISO 文件的默认位置。",
