    "explanation_title": "了解 NAT 与 PAT",
    "explanation_intro": "网络地址转换 (NAT) 和端口地址转换 (PAT) 是将一个 IP 地址空间映射到另一个空间的技术，主要用于节省有限的公网 IPv4 地址或解决子网冲突。",
    "nat_expl_title": "1. 什么是 NAT？",
    "nat_expl_desc": "NAT 以 1 对 1 的方式转换 IP 地址。它可以是静态的（将一个私有 IP 永久映射到一个公网 IP，适合面向公网的服务器）或动态的（根据需求从池中为私有主机分配公网 IP。一旦公网 IP 分配完毕，后续主机将被阻塞直到 IP 释放）。端口号不被修改。",
    "pat_expl_title": "2. 什么是 PAT (NAT 过载)？",
    "pat_expl_desc": "PAT (或端口地址转换 / NAT Overload) 以多对一 (N 对 1) 的方式转换 IP 地址和源端口号。多个私有主机通过分配唯一的源端口共享单个公网 IP 地址（例如 192.168.1.10:5000 和 192.168.1.11:5000 映射到 203.0.113.10:1024 和 203.0.113.10:1025）。这是家庭路由器和企业互联网访问的标准方法。",
    "comparison_table_title": "比较摘要",
    "comp_header_feature": "功能",
    "comp_header_nat": "NAT (1 对 1)",
    "comp_header_pat": "PAT (N 对 1 / 过载)",
