    "stratum0_examples": "GPS 接收器、原子钟（铯/铷）、无线电钟（DCF77、WWVB、MSF）、PPS（每秒脉冲）源",
    "stratum1_label": "第 1 层 — 主 NTP 服务器",
    "stratum1_desc": "服务器直接连接到 Stratum 0 参考时钟。这些是可通过网络访问的最准确的 NTP 服务器。通常用作顶级池服务器。",
    "stratum1_examples": "time.nist.gov、time.cloudflare.com、ntp1.example.com（带 GPS）、pool.ntp.org Stratum 1 成员",
    "stratum2_label": "第 2 层 — 辅助服务器",
    "stratum2_desc": "从 Stratum 1 服务器同步。适合作为大多数企业和公共部署的参考。引入一点额外的不确定性。",
    "stratum2_examples": "pool.ntp.org 服务器、区域 NTP 服务器、企业 NTP 基础设施对等点",
    "stratum3_label": "第 3 层 — 三级服务器",
    "stratum3_desc": "从 Stratum 2 同步。对于几乎所有实际应用来说仍然足够准确。典型用于下游企业 NTP 服务器。",
    "stratum3_examples": "分支机构NTP服务器、二级企业NTP中继",
    "stratum4_15_label": "层 4–15 — 附加层",
    "stratum4_15_desc": "每个后续层都会添加一个层跃点。最大可用层数为 15。每一跳的准确性都会略有下降，但对于大多数应用程序来说仍然足够。 5层以上请谨慎使用。",
    "stratum4_15_examples": "深层企业层次结构、隔离网络、嵌入式设备 NTP 客户端",
    "stratum16_label": "第 16 层 — 不同步",
    "stratum16_desc": "层值为 16 表示服务器已失去同步，不应用作时间源。客户会拒绝它。",
    "stratum16_examples": "ntpd/chronyd 已丢失所有上游源，在初始同步之前新启动的守护进程",
    "note_label": "注释",
    "notes_text": "最大可用层数为 15。层数 16 表示不同步。 16 以上的值被保留。当服务器发送 Kiss-o'-Death (KoD) 数据包时，stratum 字段设置为 0，并且 refid 对原因进行编码。",
